package com.bank.portal.config;
import com.bank.portal.repository.*; import java.util.*; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.*;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(StaffUserRepository staff, CustomerUserRepository customers){return username->staff.findByUsername(username).<UserDetails>map(u->new User(u.getUsername(),u.getPassword(),List.of(new SimpleGrantedAuthority("ROLE_STAFF")))).or(()->customers.findByUsernameOrCustomerEmail(username,username).map(u->new User(u.getUsername(),u.getPassword(),List.of(new SimpleGrantedAuthority("ROLE_CUSTOMER"))))).orElseThrow(()->new UsernameNotFoundException("Unknown user"));}
 @Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/auth/**","/error","/h2-console/**").permitAll().requestMatchers(HttpMethod.POST,"/api/account-requests").permitAll().requestMatchers("/api/staff/**","/api/customers/**","/api/merchants/**").hasRole("STAFF").requestMatchers(HttpMethod.POST,"/api/cards","/api/cards/*/status").hasRole("STAFF").requestMatchers(HttpMethod.POST,"/api/transactions/purchase").hasRole("CUSTOMER").requestMatchers("/api/**").hasAnyRole("STAFF","CUSTOMER").anyRequest().permitAll()).headers(h->h.frameOptions(f->f.sameOrigin())).httpBasic(Customizer.withDefaults()).build();}
 @Bean(name="corsConfigurationSource") CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOriginPatterns(List.of("http://localhost:*"));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
